    constexpr size_t kRealtimeFilterLutSize = 513;
    constexpr size_t kDiodeCurveLutSize = 2049;
    constexpr size_t kModulationSineLutSize = 4097;
    constexpr float kReverbV4SelectionFloor = 3.5f;
    constexpr float kReverbV5SelectionFloor = 4.5f;
    // PAD V3 is intentionally an octave texture rather than a pair of audible
    // harmony voices.  Four slightly offset +12 voices produce slow beating;
    // a small projection of their own diffuse tank is sent through them again
    // so +24 appears only on later recirculations.
    constexpr std::array<float, 4> kReverbPadOctavePitchRatios {
        1.99653745f, // +12 semitones, -3 cents
        2.00346875f, // +12 semitones, +3 cents
        1.99423129f, // +12 semitones, -5 cents
        2.00578451f  // +12 semitones, +5 cents
    };
    constexpr float kReverbPadMinimumTankDecaySeconds = 3.80f;
    constexpr float kReverbPadMaximumTankDecaySeconds = 8.00f;
    constexpr float kReverbPadMaximumTailAllowanceSeconds =
        kReverbPadMaximumTankDecaySeconds * 1.25f + 0.42f;

    float calculateReverbPadTankDecaySeconds(
        float ordinaryDecaySeconds) noexcept
    {
        const float normalizedDecay = juce::jlimit(
            0.0f,
            1.0f,
            (ordinaryDecaySeconds - 0.2f) / (12.0f - 0.2f));
        return kReverbPadMinimumTankDecaySeconds
            + normalizedDecay
                * (kReverbPadMaximumTankDecaySeconds
                   - kReverbPadMinimumTankDecaySeconds);
    }
    // V4 is the rack's guitar-focused architectural reverb. Its shortest
    // geometry is already hall-sized; Decay then grows the same tank smoothly
    // to a cathedral-sized endpoint by six seconds. RT60 remains independent
    // because the per-line feedback gains are derived from these real lengths.
    constexpr float kReverbV4MinimumTankSizeScale = 1.85f;
    constexpr float kReverbV4MaximumTankSizeScale = 2.50f;
    constexpr float kReverbV4SizeGrowthStartSeconds = 0.2f;
    constexpr float kReverbV4SizeGrowthFullSeconds = 6.0f;

    float calculateReverbV4LongFieldAmount(
        float sizeScale) noexcept;

    float calculateReverbV4TankSizeScale(
        float engineVersion,
        float decaySeconds) noexcept
    {
        if (engineVersion < kReverbV4SelectionFloor)
            return 1.0f;

        const float proportion =
            juce::jlimit(
                0.0f,
                1.0f,
                (decaySeconds
                 - kReverbV4SizeGrowthStartSeconds)
                    / (kReverbV4SizeGrowthFullSeconds
                       - kReverbV4SizeGrowthStartSeconds));
        const float smoothProportion =
            proportion
            * proportion
            * (3.0f - 2.0f * proportion);
        return kReverbV4MinimumTankSizeScale
            + (kReverbV4MaximumTankSizeScale
               - kReverbV4MinimumTankSizeScale)
                * smoothProportion;
    }

    int sanitizeReverbV5VoiceIndex(float value) noexcept
    {
        if (! std::isfinite(value))
            return S13NAMRack::studioReverbVoice;
        return juce::jlimit<int>(
            static_cast<int>(S13NAMRack::studioReverbVoice),
            static_cast<int>(S13NAMRack::roomReverbVoice),
            static_cast<int>(std::floor(value + 0.5f)));
    }

    float calculateSmoothReverbSize(
        float decaySeconds,
        float growthStartSeconds,
        float growthFullSeconds,
        float minimumScale,
        float maximumScale) noexcept
    {
        const float proportion = juce::jlimit(
            0.0f,
            1.0f,
            (decaySeconds - growthStartSeconds)
                / juce::jmax(
                    0.001f,
                    growthFullSeconds - growthStartSeconds));
        const float smoothProportion =
            proportion * proportion * (3.0f - 2.0f * proportion);
        return minimumScale
            + (maximumScale - minimumScale) * smoothProportion;
    }

    float calculateReverbV5TankSizeScale(
        float engineVersion,
        int voiceIndex,
        float decaySeconds) noexcept
    {
        if (engineVersion < kReverbV5SelectionFloor
            || voiceIndex == S13NAMRack::studioReverbVoice)
        {
            // This call, including its arithmetic order, is the exact V4 path.
            return calculateReverbV4TankSizeScale(
                engineVersion, decaySeconds);
        }

        switch (voiceIndex)
        {
            case S13NAMRack::plateReverbVoice:
                return calculateSmoothReverbSize(
                    decaySeconds, 0.2f, 4.0f, 1.30f, 1.85f);
            case S13NAMRack::hallReverbVoice:
                return calculateSmoothReverbSize(
                    decaySeconds, 0.2f, 8.0f, 2.05f, 2.50f);
            case S13NAMRack::roomReverbVoice:
                return calculateSmoothReverbSize(
                    decaySeconds, 0.2f, 3.2f, 0.72f, 1.18f);
            default:
                break;
        }
        return calculateReverbV4TankSizeScale(
            engineVersion, decaySeconds);
    }

    float calculateReverbV5LowDecayRatio(
        float engineVersion,
        int voiceIndex,
        float tankSizeScale,
        float voiceBassDecay) noexcept
    {
        if (engineVersion < kReverbV5SelectionFloor
            || voiceIndex == S13NAMRack::studioReverbVoice)
        {
            // Studio keeps the exact V4 low-frequency RT60 relationship.
            return engineVersion >= kReverbV4SelectionFloor
                ? 0.90f
                    + 0.06f
                        * calculateReverbV4LongFieldAmount(
                            tankSizeScale)
                : 0.82f;
        }
        return juce::jlimit(0.55f, 1.05f, voiceBassDecay);
    }

    float calculateReverbV4LongFieldAmount(
        float sizeScale) noexcept
    {
        return juce::jlimit(
            0.0f,
            1.0f,
            (sizeScale - kReverbV4MinimumTankSizeScale)
                / (kReverbV4MaximumTankSizeScale
                   - kReverbV4MinimumTankSizeScale));
    }

    struct ModulationSineLut
    {
        ModulationSineLut()
        {
            for (size_t index = 0;
                 index < kModulationSineLutSize;
                 ++index)
            {
                const float phase =
                    juce::MathConstants<float>::twoPi
                    * static_cast<float>(index)
                    / static_cast<float>(
                        kModulationSineLutSize - 1);
                values[index] = std::sin(phase);
            }
        }

        std::array<float, kModulationSineLutSize> values {};
    };

    const ModulationSineLut& getModulationSineLut()
    {
        static const ModulationSineLut lut;
        return lut;
    }

    float wrapModulationPhase(float phase) noexcept
    {
        constexpr float twoPi =
            juce::MathConstants<float>::twoPi;
        while (phase >= twoPi)
            phase -= twoPi;
        while (phase < 0.0f)
            phase += twoPi;
        return phase;
    }

    float lookupModulationSine(float phase) noexcept
    {
        phase = wrapModulationPhase(phase);
        const float position =
            phase
            * static_cast<float>(
                kModulationSineLutSize - 1)
            / juce::MathConstants<float>::twoPi;
        const auto lowerIndex = static_cast<size_t>(position);
        const auto upperIndex = juce::jmin(
            lowerIndex + 1,
            kModulationSineLutSize - 1);
        const float fraction =
            position - static_cast<float>(lowerIndex);
        const auto& lut = getModulationSineLut();
        return lut.values[lowerIndex]
            + (lut.values[upperIndex]
               - lut.values[lowerIndex])
                * fraction;
    }

    struct DiodeCurveLut
    {
        DiodeCurveLut()
        {
            for (size_t index = 0;
                 index < kDiodeCurveLutSize;
                 ++index)
            {
                const float exponent =
                    -5.0f
                    + 10.0f * static_cast<float>(index)
                        / static_cast<float>(
                            kDiodeCurveLutSize - 1);
                sinhValues[index] = std::sinh(exponent);
                coshValues[index] = std::cosh(exponent);
            }
        }

        std::array<float, kDiodeCurveLutSize> sinhValues {};
        std::array<float, kDiodeCurveLutSize> coshValues {};
    };

    const DiodeCurveLut& getDiodeCurveLut()
    {
        static const DiodeCurveLut lut;
        return lut;
    }

    float safeFilterMaximum(double sampleRate, float nominalMinimum, float nominalMaximum)
    {
        return juce::jmax(nominalMinimum,
                          juce::jmin(nominalMaximum,
                                     static_cast<float>(sampleRate * 0.475)));
    }

    void prepareRealtimeFilterLut(std::vector<S13IIRCoefficientSet>& lut,
                                  double sampleRate,
                                  float nominalMinimum,
                                  float nominalMaximum,
                                  bool highPass)
    {
        const float safeMinimum = juce::jmax(1.0f, nominalMinimum);
        const float safeMaximum = safeFilterMaximum(sampleRate, safeMinimum, nominalMaximum);
        const double logMinimum = std::log(static_cast<double>(safeMinimum));
        const double logRange = std::log(static_cast<double>(safeMaximum)) - logMinimum;
        lut.resize(kRealtimeFilterLutSize);

        for (size_t index = 0; index < lut.size(); ++index)
        {
            const double proportion = static_cast<double>(index)
                / static_cast<double>(lut.size() - 1);
            const float frequency = static_cast<float>(std::exp(logMinimum + proportion * logRange));
            const auto coefficients = highPass
                ? juce::dsp::IIR::Coefficients<float>::makeHighPass(sampleRate, frequency)
                : juce::dsp::IIR::Coefficients<float>::makeLowPass(sampleRate, frequency);
            const auto& source = coefficients->coefficients;
            jassert(source.size() == lut[index].size());
            for (size_t coefficient = 0; coefficient < lut[index].size(); ++coefficient)
                lut[index][coefficient] = source[static_cast<int>(coefficient)];
        }
    }

    const S13IIRCoefficientSet& lookupRealtimeFilterLut(
        const std::vector<S13IIRCoefficientSet>& lut,
        double sampleRate,
        float frequency,
        float nominalMinimum,
        float nominalMaximum) noexcept
    {
        jassert(! lut.empty());
        const float safeMinimum = juce::jmax(1.0f, nominalMinimum);
        const float safeMaximum = safeFilterMaximum(sampleRate, safeMinimum, nominalMaximum);
        const double logMinimum = std::log(static_cast<double>(safeMinimum));
        const double logRange = std::log(static_cast<double>(safeMaximum)) - logMinimum;
        const double position = logRange > 0.0
            ? (std::log(static_cast<double>(juce::jlimit(safeMinimum, safeMaximum, frequency))) - logMinimum)
                / logRange
            : 0.0;
        const auto index = static_cast<size_t>(juce::jlimit(
            0,
            static_cast<int>(lut.size() - 1),
            static_cast<int>(std::lround(position * static_cast<double>(lut.size() - 1)))));
        return lut[index];
    }

    void writeRealtimeFilterCoefficients(juce::dsp::IIR::Filter<float>& filter,
                                         const S13IIRCoefficientSet& coefficients) noexcept
    {
        jassert(filter.coefficients != nullptr);
        if (filter.coefficients == nullptr)
            return;

        auto& destination = filter.coefficients->coefficients;
        jassert(destination.size() == coefficients.size());
        if (destination.size() != coefficients.size())
            return;

        for (size_t coefficient = 0; coefficient < coefficients.size(); ++coefficient)
            destination.set(static_cast<int>(coefficient), coefficients[coefficient]);
    }

    void writeRealtimeFilterCoefficients(juce::dsp::IIR::Filter<float>& left,
                                         juce::dsp::IIR::Filter<float>& right,
                                         const S13IIRCoefficientSet& coefficients) noexcept
    {
        writeRealtimeFilterCoefficients(left, coefficients);
        if (right.coefficients != left.coefficients)
            writeRealtimeFilterCoefficients(right, coefficients);
    }

    bool smoothRealtimeFilterCoefficients(
        juce::dsp::IIR::Filter<float>& left,
        juce::dsp::IIR::Filter<float>& right,
        const S13IIRCoefficientSet& target,
        float smoothingCoefficient) noexcept
    {
        if (left.coefficients == nullptr
            || right.coefficients == nullptr)
            return false;

        auto& leftCoefficients =
            left.coefficients->coefficients;
        auto& rightCoefficients =
            right.coefficients->coefficients;
        if (leftCoefficients.size() != target.size()
            || rightCoefficients.size() != target.size())
        {
            return false;
        }

        auto* const leftRaw =
            leftCoefficients.getRawDataPointer();
        auto* const rightRaw =
            rightCoefficients.getRawDataPointer();
        const bool sharedCoefficients =
            leftRaw == rightRaw;
        bool smoothing = false;
        for (size_t index = 0;
             index < target.size();
             ++index)
        {
            const float difference =
                target[index] - leftRaw[index];
            const float next =
                std::abs(difference) <= 1.0e-7f
                    ? target[index]
                    : leftRaw[index]
                        + difference
                            * smoothingCoefficient;
            leftRaw[index] = next;
            if (! sharedCoefficients)
                rightRaw[index] = next;
            smoothing =
                smoothing
                || std::abs(target[index] - next)
                    > 1.0e-6f;
        }
        return smoothing;
    }

